sys_ui_action.script:
var workloadSysIds = [];
var workloadGr = new GlideRecord("x_illu2_illumio_illumio_pce_workload");
workloadGr.addEncodedQuery(current.pce_workload_condition);
workloadGr.orderByDesc("sys_updated_on");
workloadGr.query();
while (workloadGr.next()) {
	workloadSysIds.push(workloadGr.getUniqueValue());
}
var htmlContent = [];
var htmlHeader = "<!DOCTYPE html> " +
        "<head>" +
        "<style>" +
        "body {" +
        "margin: 10;" +
        "width: 100%;" +
        "}" +
        "table.ILLUMIO {" +
        "font-size: 15px;" +
        "font-family: verdana;" +
        "font-weight: normal;" +
        "border: 1px solid black;" +
        "}" +
        "td.ILLUMIO {" +
        "padding: 8px 50px 8px 8px;" +
        "border: 1px solid black;" +
        "}" +
        "th.ILLUMIO {" +
        "border: 1px solid black;" +
        "padding: 8px 50px 8px 8px;" +
        "}" +
        "</style>" +
        "</head>" +
        "<body>";
var tableHeading = "<table class=\"ILLUMIO\"><tr class=\"ILLUMIO\"><th class=\"ILLUMIO\">Illumio PCE Workload</th><th class=\"ILLUMIO\">Illumio Label Dimension</th><th class=\"ILLUMIO\">CMDB Value</th><th class=\"ILLUMIO\">PCE Value</th></tr>";
var trStart = "<tr class=\"ILLUMIO\">";
var trEnd = "</tr>";
var tdStart = "<td class=\"ILLUMIO\">";
var tdEnd = "</td>";
htmlContent.push(htmlHeader);
htmlContent.push(tableHeading);
var rowCounter = 0;
var wlFieldValueGr = new GlideRecord("x_illu2_illumio_illumio_pce_workload_field_value");
wlFieldValueGr.addEncodedQuery(current.pce_wl_field_value_condition);
wlFieldValueGr.addQuery("illumio_pce_workload", "IN", workloadSysIds);
workloadGr.orderByDesc("sys_updated_on");
workloadGr.orderBy("illumio_pce_workload");
wlFieldValueGr.setLimit(101);
wlFieldValueGr.query();
if (!wlFieldValueGr.hasNext()) {
	gs.addInfoMessage("No matching records found;");
	action.setRedirectURL(current);
}
while (wlFieldValueGr.next()) {
	rowCounter -= -1;
	htmlContent.push(trStart);
	htmlContent.push(tdStart);
	htmlContent.push(wlFieldValueGr.getDisplayValue("illumio_pce_workload"));
	htmlContent.push(tdEnd);
	htmlContent.push(tdStart);
	htmlContent.push(wlFieldValueGr.getDisplayValue("illumio_label_dimension"));
	htmlContent.push(tdEnd);
	htmlContent.push(tdStart);
	htmlContent.push(wlFieldValueGr.getValue("cmdb_value"));
	htmlContent.push(tdEnd);
	htmlContent.push(tdStart);
	htmlContent.push(wlFieldValueGr.getValue("pce_value"));
	htmlContent.push(tdEnd);
	htmlContent.push(trEnd);

	if (rowCounter > 100) {
		// show last row to open the view in ServiceNow native table view
		htmlContent.push("<tr><td colspan=\"4\">The Preview Record is limited to only recently updated 100 records. For the complete list, please navigate to ServiceNow's native list view.</td></tr>");
		break;
	}
}
htmlContent.push("</table></body>");

current.setValue("record_preview", htmlContent.join(" "));
current.update();
action.setRedirectURL(current);
